use semio_framework_test_fixtures::fixture_text;
use super::*;
/// 🧪️ Portable request sharing/refusal/departure agrees with independent ordered membership.
#[test]
fn fixed_request_owners_match_portable_consumer_transitions(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let mut owner=FixedRequestOwners::<u64,u64,3,4>::new();let mut oracle=std::collections::BTreeMap::new();
 for row in fixture["actions"].as_array().unwrap(){let scope=row["scope"].as_u64().unwrap()as u32;match row["kind"].as_str().unwrap(){
  "admit"=>{let consumer=row["consumer"].as_u64().unwrap();let request=row["request"].as_u64().unwrap();let admitted=owner.admit(scope,consumer,request);assert_eq!(admitted.map(|admission|admission.owner.index()as u64),row["owner"].as_u64());if let Some(admission)=admitted{oracle.insert((scope,consumer),request);assert_eq!(owner.references(admission.owner)as u64,row["references"].as_u64().unwrap());}for(&(scope,consumer),&request)in &oracle{assert_eq!(owner.binding(scope,consumer),owner.lookup(scope,request));}},
  "remove"=>{let consumer=row["consumer"].as_u64().unwrap();let lease=owner.remove_consumer(scope,consumer).unwrap();oracle.remove(&(scope,consumer));assert_eq!(lease.index()as u64,row["owner"].as_u64().unwrap());assert_eq!(owner.references(lease)as u64,row["references"].as_u64().unwrap());},
  "release"=>{let lease=owner.lookup(scope,row["request"].as_u64().unwrap()).unwrap();assert_eq!(owner.release(lease),row["accepted"].as_bool().unwrap());},_=>panic!("request corpus operation")}}
 assert!(oracle.is_empty());assert!((0..3).all(|index|owner.at(index).is_none()));
 let mut a=FixedRequestOwners::<u64,u64,1,1>::new();let mut b=FixedRequestOwners::<u64,u64,1,1>::new();let old=a.admit(1,1,1).unwrap().owner;let foreign=b.admit(1,1,1).unwrap().owner;
 a.remove_consumer(1,1);assert!(!a.release(foreign));assert!(a.release(old));let live=a.admit(1,1,2).unwrap().owner;assert!(!a.release(old));assert_eq!(a.binding(1,1),Some(live));
 println!("[DEBUG] fixed scoped request owners preserve sharing, distinct requests, refused rebind, original retirement and stale/foreign release");
}

/// 🧪️ Original long text, partial cancellation and terminal authority consume exact bounded receipts.
#[test]
fn request_text_and_terminals_match_portable_boundaries(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["identityCases"].as_array().unwrap(){
  let length=row["bytes"].as_u64().unwrap()as usize;let original="x".repeat(length);let segments=[b"source".as_slice(),original.as_bytes()];let mut cursor=ContentRequestKeyCursor::new(&segments).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:257,maximum_capacity_bytes:length,maximum_release_bytes:length,maximum_depth:1};let mut hashed=0;
  while cursor.key().is_none(){let step=cursor.step(&segments,grant).unwrap();assert!(step.progress.copied_bytes<=257);hashed+=step.progress.copied_bytes;}assert_eq!(hashed,length+6+16);
  let mut oracle=blake3::Hasher::new();for segment in segments{oracle.update(&(segment.len()as u64).to_le_bytes());oracle.update(segment);}assert_eq!(cursor.key().unwrap().digest(),oracle.finalize().as_bytes());
  let mut owners=FixedRequestOwners::<u64,u64,2,2>::new();let denied=owners.prepare_consumer(1,1,&original,RetainedCloneGrant::default());if !row["accepted"].as_bool().unwrap(){assert!(denied.is_err());continue;}assert_eq!(denied.unwrap(),RequestTextStep::default());assert!(!owners.has_consumer(1));
  let birth=owners.prepare_consumer(1,1,&original,grant).unwrap();assert!(!birth.ready);assert_eq!(birth.progress.retained_capacity_bytes,length);let demand=owners.consumer_close_demand(owners.consumer_index(1,1).unwrap()).unwrap();assert_eq!(demand.release_bytes,length);
  assert!(owners.remove_consumer(1,1).is_none());let mut short=grant;short.maximum_release_bytes=length-1;assert_eq!(owners.retire_consumer_step(1,short),Some(Default::default()));assert!(owners.has_consumer(1));let retired=owners.retire_consumer_step(1,grant).unwrap();assert_eq!(retired.released_bytes,length);assert!(!owners.has_consumer(1));
  let mut copied=0;loop{let step=owners.prepare_request(1,10,&original,grant).unwrap();if step.progress.retained_capacity_bytes==0{copied+=step.progress.copied_bytes;}assert!(step.progress.copied_bytes<=257);if step.ready{break;}}assert_eq!(copied,length);let owner=owners.lookup(1,10).unwrap();assert_eq!(owners.request_name(owner),Some(original.as_str()));assert!(!owners.ready(owner));assert_eq!(owners.stage(1,1,10).unwrap().owner,owner);assert!(!owners.ready(owner));assert!(owners.admit(1,1,10).is_some());assert!(owners.ready(owner));owners.remove_consumer(1,1);assert!(!owners.release(owner));assert_eq!(owners.retire_request_step(owner,grant).unwrap().released_bytes,length);assert!(owners.release(owner));
 }
 let mut owners=FixedRequestOwners::<u64,u64,2,2>::new();let owner=owners.admit(1,1,10).unwrap().owner;owners.admit(1,2,10).unwrap();let mut source=RequestSourceVersion{base_revision:1,generation:1,canonical_revision:[1;32]};
 for row in fixture["terminalCases"].as_array().unwrap(){let job=row["job"].as_u64().unwrap();let accepted=match row["kind"].as_str().unwrap(){"begin"=>owners.begin_execution(owner,source,job),"fault"=>owners.record_terminal(owner,source,job,RequestTerminalKind::Faulted),"cancel"=>owners.record_terminal(owner,source,job,RequestTerminalKind::Cancelled),"validate"=>owners.record_terminal(owner,source,job,RequestTerminalKind::Validated),"retry"=>owners.retry(owner,source),"newRevision"=>{source.canonical_revision=[2;32];owners.begin_execution(owner,source,job)},_=>panic!("terminal fixture operation")};assert_eq!(accepted,row["accepted"].as_bool().unwrap());}
 assert_eq!(owners.remove_consumer(1,1),Some(owner));assert_eq!(owners.references(owner),1);assert!(!owners.begin_execution(owner,source,16));assert!(!owners.release(owner));owners.remove_consumer(1,2);assert!(owners.release(owner));assert!(!owners.record_terminal(owner,source,14,RequestTerminalKind::Faulted));
 println!("[DEBUG] long identity boundaries, denied birth, partial custody cancellation, BLAKE3 framed selectors and original terminal retry agree with portable cases");
}

/// 🧪️ Original consumer authority funds selector birth, version restart and partial candidate cancellation.
#[test]
fn request_selector_preserves_original_binding_until_verified_promotion(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["selectorCases"].as_array().unwrap(){
  let window="w".repeat(row["consumerBytes"].as_u64().unwrap()as usize);let source="s".repeat(row["sourceBytes"].as_u64().unwrap()as usize);let chunk=row["chunkBytes"].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:131_072,maximum_release_bytes:131_072,maximum_depth:1};let small=RetainedCloneGrant{maximum_copy_bytes:chunk,..grant};let mut owners=FixedRequestOwners::<ContentRequestKey,u64,3,3>::new();
  loop{let step=owners.prepare_consumer(1,70,&window,small).unwrap();assert!(step.progress.fits(small));if step.ready{break;}}
  let old_key=ContentRequestKey::from_segments(&[b"old"]).unwrap();let old=owners.admit(1,70,old_key).unwrap().owner;let mut version=RequestCandidateVersion{source:RequestSourceVersion{base_revision:1,generation:1,canonical_revision:[1;32]},consumer_generation:1,consumer_revision:[1;32]};let segments=[b"static".as_slice(),b"loadCase".as_slice(),source.as_bytes()];
  assert_eq!(owners.prepare_selector(1,70,version,&segments,Default::default()).unwrap(),RequestSelectorStep::default());assert!(owners.selector(1,70,version).is_none());let birth=owners.prepare_selector(1,70,version,&segments,grant).unwrap();assert!(birth.progress.retained_capacity_bytes>0);assert!(birth.progress.fits(grant));let initialized=owners.prepare_selector(1,70,version,&segments,grant).unwrap();assert!(initialized.progress.copied_bytes>0);let key=loop{let step=owners.prepare_selector(1,70,version,&segments,small).unwrap();assert!(step.progress.fits(small));if let Some(key)=step.key{break key;}};
  let mut oracle=blake3::Hasher::new();for segment in segments{oracle.update(&(segment.len()as u64).to_le_bytes());oracle.update(segment);}assert_eq!(key.digest(),oracle.finalize().as_bytes());let candidate=owners.stage_controlled(1,70,key,grant).unwrap().admission.owner;assert_eq!(owners.live_binding(1,70),Some(old));assert_eq!(owners.binding(1,70),Some(candidate));assert_eq!(owners.references(old),1);assert_eq!(owners.references(candidate),1);assert!(owners.admit_controlled(1,70,key,Default::default()).is_none());assert_eq!(owners.live_binding(1,70),Some(old));
  loop{let step=owners.prepare_request(1,key,&source,small).unwrap();assert!(step.progress.fits(small));if step.ready{break;}}assert!(owners.admit_controlled(1,70,key,grant).is_some());assert_eq!(owners.live_binding(1,70),Some(candidate));assert_eq!(owners.references(old),0);assert!(owners.release(old));
  version.consumer_revision=[row["changedConsumerRevision"].as_u64().unwrap()as u8;32];assert!(owners.selector(1,70,version).is_none());assert_eq!(owners.prepare_selector(1,70,version,&segments,Default::default()).unwrap(),RequestSelectorStep::default());assert_eq!(owners.live_binding(1,70),Some(candidate));let restarted=owners.prepare_selector(1,70,version,&segments,grant).unwrap();assert_eq!(restarted.progress.retained_capacity_bytes,0);assert!(restarted.progress.copied_bytes>0);
  owners.remove_consumer(1,70);assert!(!owners.has_consumer(2));assert!(owners.has_consumer(1));let quote=owners.consumer_close_demand(owners.consumer_index(1,70).unwrap()).unwrap();let short=RetainedCloneGrant{maximum_release_bytes:quote.release_bytes-1,..grant};assert_eq!(owners.retire_consumer_step(1,short),Some(Default::default()));let cursor_return=owners.retire_consumer_step(1,grant).unwrap();assert_eq!(cursor_return.released_bytes,quote.release_bytes);assert!(owners.has_consumer(1));assert_eq!(owners.retire_consumer_step(1,grant).unwrap().released_bytes,window.len());assert!(!owners.has_consumer(1));assert_eq!(owners.retire_request_step(candidate,grant).unwrap().released_bytes,source.len());assert!(owners.release(candidate));
 }
 println!("[DEBUG] 16KiB source / 64KiB window selector, changed config revision, denied admission, previous live sibling and original partial cursor closure remain exact and funded");
}

/// 🧪️ Long physical source identity derives new snapshot operands under original-version custody.
#[test]
fn original_source_lookup_matches_portable_reordered_operands(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["lookupCases"].as_array().unwrap(){let length=row["sourceBytes"].as_u64().unwrap()as usize;let original=format!("{}{}","s".repeat(length-1),row["originalSuffix"].as_str().unwrap());let candidates:Vec<_>=row["candidateSuffixes"].as_array().unwrap().iter().map(|suffix|format!("{}{}","s".repeat(length-1),suffix.as_str().unwrap())).collect();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:row["chunkBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:131_072,maximum_release_bytes:131_072,maximum_depth:1};let mut registry=FixedRequestOwners::<u64,u64,1,1>::new();let owner=registry.stage(1,1,1).unwrap().owner;while !registry.prepare_request(1,1,&original,grant).unwrap().ready{}registry.admit(1,1,1).unwrap();let mut version=RequestSourceVersion{base_revision:1,generation:1,canonical_revision:[1;32]};assert_eq!(registry.source_lookup_step(owner,version,None,Default::default()).unwrap().progress,Default::default());let position=loop{let position=registry.source_lookup(owner,version).map_or(0,|(position,_)|position);let step=registry.source_lookup_step(owner,version,candidates.get(position).map(String::as_str),grant).unwrap();assert!(step.progress.fits(grant));if step.outcome==RequestLookupOutcome::Matched{break step.position;}assert_eq!(step.outcome,RequestLookupOutcome::Searching);};assert_eq!(position,row["matchedPosition"].as_u64().unwrap()as usize);version.canonical_revision=[2;32];assert!(registry.source_lookup(owner,version).is_none());loop{let step=registry.source_lookup_step(owner,version,Some(&original),grant).unwrap();assert!(step.progress.fits(grant));if step.outcome==RequestLookupOutcome::Matched{assert_eq!(step.position,0);break;}}registry.remove_consumer(1,1);registry.retire_request_step(owner,grant);assert!(registry.release(owner));let reused=registry.admit(1,2,2).unwrap().owner;assert_eq!(reused.index(),owner.index());assert!(registry.source_lookup(reused,version).is_none());registry.remove_consumer(1,2);assert!(registry.release(reused));}
 println!("[DEBUG] chunked original6.5KiB source lookup resolves current ordinal2 then canonical-revised ordinal0 without aliasing source identity");
}

#[test]
fn provisional_request_consumers_match_portable_live_and_pending_outputs(){
 assert_original_text_close_quotes();
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut owner=FixedRequestOwners::<u64,u64,2,2>::new();for row in fixture["stageTransitions"].as_array().unwrap(){let consumer=row["consumer"].as_u64().unwrap();let request=row["request"].as_u64().unwrap();let accepted=match row["op"].as_str().unwrap(){"admit"=>owner.admit(1,consumer,request).is_some(),"stage"=>owner.stage(1,consumer,request).is_some(),"remove"=>owner.remove_consumer(1,consumer).is_some(),_=>owner.lookup(1,request).is_some_and(|lease|owner.release(lease))};assert_eq!(accepted,row["accepted"].as_bool().unwrap());assert_eq!(owner.live_binding(1,1).map(|lease|owner.key(lease).unwrap().1),row["live1"].as_u64());assert_eq!(owner.binding(1,1).map(|lease|owner.key(lease).unwrap().1),row["pending1"].as_u64().or(row["live1"].as_u64()));for(key,field)in [(10,"ref10"),(20,"ref20")]{let references=owner.lookup(1,key).map_or(0,|lease|owner.references(lease));assert_eq!(references,row[field].as_u64().unwrap()as usize);}}
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:257,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:1};for row in fixture["comparisonCases"].as_array().unwrap(){let original=row["original"].as_str().unwrap();let candidate=row["candidate"].as_str().unwrap();let mut registry=FixedRequestOwners::<u64,u64,1,1>::new();while !registry.prepare_request(1,1,original,grant).unwrap().ready{}let step=registry.prepare_request(1,1,candidate,grant).unwrap();assert_eq!(step.ready,row["accepted"].as_bool().unwrap());assert_eq!(step.fault,row["fault"].as_str());assert!(step.progress.copied_bytes>0);assert!(step.progress.fits(grant));let lease=registry.lookup(1,1).unwrap();assert_eq!(registry.request_name(lease),Some(original));registry.retire_request_step(lease,grant);assert!(registry.release(lease));}eprintln!("[DEBUG] portable provisional live/pending sibling authority and paid exact-key collision receipts preserve original custody");
}

fn assert_original_text_close_quotes(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🎫️requests/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:257,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:1};
 for row in fixture["closeCases"].as_array().unwrap(){
  let length=row["sourceBytes"].as_u64().unwrap()as usize;let target=row["copiedBytes"].as_u64().unwrap()as usize;let original="x".repeat(length);let mut registry=FixedRequestOwners::<u64,u64,1,1>::new();registry.prepare_request(1,1,&original,grant).unwrap();let owner=registry.lookup(1,1).unwrap();let mut copied=0;while copied<target{let step=registry.prepare_request(1,1,&original,RetainedCloneGrant{maximum_copy_bytes:257.min(target-copied),..grant}).unwrap();copied+=step.progress.copied_bytes;}
  let pointer=registry.request_names[owner.index()].as_ref().unwrap().original.as_ptr();let quote=registry.request_close_demand(owner).unwrap();assert_eq!(quote.copy_bytes,std::mem::size_of::<Option<super::ConsumerText>>());assert!(quote.copy_bytes>0);for copy in [0,quote.copy_bytes-1]{assert_eq!(registry.retire_request_step(owner,RetainedCloneGrant{maximum_copy_bytes:copy,..grant}),Some(Default::default()));assert_eq!(registry.request_names[owner.index()].as_ref().unwrap().original.as_ptr(),pointer);assert_eq!(registry.request_names[owner.index()].as_ref().unwrap().original.len(),target);assert!(!registry.release(owner));}assert_eq!(registry.retire_request_step(owner,RetainedCloneGrant{maximum_release_bytes:quote.release_bytes-1,..grant}),Some(Default::default()));let receipt=registry.retire_request_step(owner,grant).unwrap();assert_eq!(receipt.copied_bytes,quote.copy_bytes);assert_eq!(receipt.released_bytes,quote.release_bytes);assert!(receipt.fits(grant));assert!(registry.release(owner));
  registry.prepare_consumer(1,1,&original,grant).unwrap();let mut copied=0;while copied<target{let step=registry.prepare_consumer(1,1,&original,RetainedCloneGrant{maximum_copy_bytes:257.min(target-copied),..grant}).unwrap();copied+=step.progress.copied_bytes;}let index=registry.consumer_index(1,1).unwrap();let lease=registry.consumers.lookup((1,1)).unwrap();let pointer=registry.names[index].as_ref().unwrap().original.as_ptr();assert!(registry.remove_consumer(1,1).is_none());let quote=registry.consumer_close_demand(index).unwrap();assert!(quote.copy_bytes>=std::mem::size_of::<Option<super::ConsumerText>>());for copy in [0,quote.copy_bytes-1]{assert_eq!(registry.retire_consumer_step(1,RetainedCloneGrant{maximum_copy_bytes:copy,..grant}),Some(Default::default()));assert_eq!(registry.names[index].as_ref().unwrap().original.as_ptr(),pointer);assert_eq!(registry.consumers.lookup((1,1)),Some(lease));}let receipt=registry.retire_consumer_step(1,grant).unwrap();assert_eq!(receipt.copied_bytes,quote.copy_bytes);assert_eq!(receipt.released_bytes,quote.release_bytes);assert!(receipt.fits(grant));assert!(!registry.has_consumer(1));let reused=registry.claim_consumer_controlled(1,1,grant).unwrap();assert!(reused.ready);assert_ne!(registry.consumers.lookup((1,1)),Some(lease));registry.remove_consumer(1,1);eprintln!("[DEBUG] original text close {} requires genuine header copy and allocation release, preserving partial custody and exact lease through denial",row["name"]);
 }
}
